/**
 * The sound of the city, made rather than downloaded.
 *
 * There are no recordings in this repository: no samples, no licence questions, and
 * nothing to fetch. Every sound here is generated by `synth.ts` and played with the Web
 * Audio API, panned by where the vehicle is relative to where the camera is looking. So a
 * matatu down Kenyatta Avenue really does come from over there, and gets louder as it
 * comes past.
 *
 * Two rules keep it from being a nuisance:
 *
 *  - nothing is created until the player has clicked (browsers refuse to start audio
 *    before a gesture, and nobody wants a game that plays sound over its own menu);
 *  - everything is mixed low, the volume control is in Settings, and it is remembered
 *    between visits.
 *
 * The graph is built once and reused: one master gain, one compressor (so a dozen matatu
 * horns at once cannot clip), and a small stable pool of voices. `synth.ts` and
 * `placement.ts` have no Web Audio in them at all, so what the city sounds like can be
 * tested in Node.
 */
import { useGame } from '../state/gameStore'
import { runtime } from '../state/runtime'
import { ENGINE_RANGE, HORN_RANGE, falloff, panOf } from './placement'
import { horn, vehicleVoices, type VehicleVoice } from './synth'

export { falloff, panOf } from './placement'

/** How many vehicles can have a continuous engine note at once. */
const ENGINES = 8
/**
 * How far a horn is asked for at all. Much further than an engine carries: hearing a
 * matatu before you can see it is most of what a Nairobi street sounds like.
 */
const HORN_AUDIBLE = HORN_RANGE
/** At most this many horns a second, however many matatus arrive at once. */
const HORN_BUDGET = 3

export interface AudioState {
  ready: boolean
  muted: boolean
  volume: number
}

export const audio: AudioState = { ready: false, muted: false, volume: 0.6 }

let context: AudioContext | null = null
let master: GainNode | null = null
let voices: VehicleVoice[] = []
let started = false
let hornsThisSecond = 0
let hornSecond = -1

/** The browser's audio clock, or null before the first gesture. */
export function audioNow(): number | null {
  return context ? context.currentTime : null
}

/**
 * Build the graph. Called on the first real user gesture; calling it again does nothing.
 * Returns false where the browser has no Web Audio at all, and the game plays on silently.
 */
export function startAudio(): boolean {
  if (started) return audio.ready
  started = true
  const Ctor =
    typeof window === 'undefined'
      ? undefined
      : (window.AudioContext ??
        (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext)
  if (!Ctor) return false

  try {
    context = new Ctor()
  } catch {
    // Some embedded browsers refuse a context outright; play on silently.
    return false
  }
  master = context.createGain()
  master.gain.value = 0
  const compressor = context.createDynamicsCompressor()
  compressor.threshold.value = -18
  compressor.ratio.value = 6
  master.connect(compressor).connect(context.destination)
  voices = vehicleVoices(context, ENGINES, master)
  audio.ready = true
  applyVolumes()
  return true
}

/** Push the player's volume choice into the graph, fading rather than jumping. */
export function applyVolumes(): void {
  if (!context || !master) return
  const target = audio.muted ? 0 : audio.volume
  master.gain.setTargetAtTime(target, context.currentTime, 0.08)
}

/** Browsers suspend audio when a tab is hidden; wake it when the player comes back. */
export function resumeAudio(): void {
  if (context?.state === 'suspended') void context.resume()
}

/** Vehicles currently sounding, keyed by their stable seed. */
const sources = new Map<number, VehicleVoice>()

/**
 * Called every frame with the nearest vehicles, nearest first. Each gets an engine note
 * panned to where it is; the ones that drop off the list fall silent.
 */
export function updateEngines(
  nearby: readonly { id: number; x: number; z: number; speed: number; kind: string }[],
): void {
  if (!context || !master) return
  const now = context.currentTime
  const player = runtime.player
  const live = new Set<number>()

  for (const vehicle of nearby) {
    if (live.size >= ENGINES) break
    const distance = Math.hypot(vehicle.x - player.x, vehicle.z - player.z)
    if (distance > ENGINE_RANGE) continue
    live.add(vehicle.id)

    let voice = sources.get(vehicle.id)
    if (!voice) {
      const free = voices.find((candidate) => !candidate.busy())
      if (!free) continue
      free.attach(vehicle.kind)
      voice = free
      sources.set(vehicle.id, voice)
    }
    voice.update(
      now,
      falloff(distance, ENGINE_RANGE),
      // An engine note rises with speed, and idles just above its base pitch.
      Math.min(1, Math.abs(vehicle.speed) / 14),
      panOf(vehicle.x - player.x, vehicle.z - player.z, runtime.camera.yaw),
    )
  }

  for (const [id, voice] of sources) {
    if (live.has(id)) continue
    voice.release(now)
    sources.delete(id)
  }
}

/**
 * A horn, from a vehicle at `x, z`. Only sounds where the player could plausibly hear it,
 * and never more than a few a second: a city full of matatus arriving at their stages at
 * once should sound like a city, not like an alarm.
 */
export function honkAt(x: number, z: number, kind: 'matatu' | 'car' = 'matatu'): void {
  if (!context || !master || audio.muted) return
  const distance = Math.hypot(x - runtime.player.x, z - runtime.player.z)
  const level = falloff(distance, HORN_AUDIBLE) * (kind === 'matatu' ? 1 : 0.6)
  if (level <= 0.004) return
  const second = Math.floor(context.currentTime)
  if (second !== hornSecond) {
    hornSecond = second
    hornsThisSecond = 0
  }
  if (hornsThisSecond >= HORN_BUDGET) return
  hornsThisSecond++

  const source = context.createBufferSource()
  source.buffer = hornBuffer(kind)
  const gain = context.createGain()
  gain.gain.value = level * 0.5
  const pan = context.createStereoPanner()
  pan.pan.value = panOf(x - runtime.player.x, z - runtime.player.z, runtime.camera.yaw)
  source.connect(gain).connect(pan).connect(master)
  source.start(context.currentTime)
  source.onended = () => {
    source.disconnect()
    gain.disconnect()
    pan.disconnect()
  }
}

/** Horn buffers are made once and shared by every blast. */
const hornBuffers = new Map<string, AudioBuffer>()
function hornBuffer(kind: 'matatu' | 'car'): AudioBuffer {
  const key = `horn:${kind}`
  let buffer = hornBuffers.get(key)
  if (!buffer && context) {
    const samples = horn(kind)
    buffer = context.createBuffer(1, samples.length, context.sampleRate)
    buffer.copyToChannel(samples, 0)
    hornBuffers.set(key, buffer)
  }
  // The map is filled on the first call, which is the same call that reads it.
  return buffer!
}

/** Stop everything: called when the game pauses or the tab goes away. */
export function silence(): void {
  if (!context || !master) return
  master.gain.setTargetAtTime(0, context.currentTime, 0.05)
}

/** Pick the sound up again after a pause. */
export function unsilence(): void {
  applyVolumes()
}

/** Tie the mixer to the player's saved settings. Called once at start-up. */
export function bindSettings(): () => void {
  const sync = () => {
    const settings = useGame.getState().settings
    audio.volume = settings.volume
    audio.muted = settings.muted
    applyVolumes()
  }
  sync()
  return useGame.subscribe(sync)
}
